def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars = []
    # Find contiguous same-color segments on each outer edge.
    for r in (0, h - 1):
        c = 0
        while c < w:
            if grid[r][c] == bg:
                c += 1
                continue
            v, a = grid[r][c], c
            while c < w and grid[r][c] == v:
                c += 1
            if c - a >= 2:
                bars.append(('h', r, a, c, v))
    for c in (0, w - 1):
        r = 0
        while r < h:
            if grid[r][c] == bg:
                r += 1
                continue
            v, a = grid[r][c], r
            while r < h and grid[r][c] == v:
                r += 1
            if r - a >= 2:
                bars.append(('v', c, a, r, v))
    # Singleton non-background cells are markers and determine ray color/count.
    singles = []
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v == bg:
                continue
            if any(0 <= r+dr < h and 0 <= c+dc < w and grid[r+dr][c+dc] == v
                   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1))):
                continue
            singles.append((r,c,v))
    out = [row[:] for row in grid]
    if not singles:
        return out
    n = len(singles)
    ray_color = singles[0][2]
    # Convert all singleton markers, then cast a width-n band inward from each edge bar.
    for r,c,_ in singles:
        out[r][c] = 4
    for orient, fixed, a, b, bar_color in bars:
        if orient == 'h':
            # Use the final n cells of the boundary segment as the projected band.
            lo, hi = max(a, b - n), b
            direction = 1 if fixed == 0 else -1
            for c in range(lo, hi):
                marker_rows = [r for r,cc,_ in singles if cc == c]
                if direction == 1:
                    stop = min(marker_rows) if marker_rows else h - 1
                    for r in range(fixed + 1, stop + 1):
                        out[r][c] = ray_color
                else:
                    stop = max(marker_rows) if marker_rows else 0
                    for r in range(fixed - 1, stop - 1, -1):
                        out[r][c] = ray_color
        else:
            lo, hi = max(a, b - n), b
            direction = 1 if fixed == 0 else -1
            for r in range(lo, hi):
                marker_cols = [c for rr,c,_ in singles if rr == r]
                if direction == 1:
                    stop = min(marker_cols) if marker_cols else w - 1
                    for c in range(fixed + 1, stop + 1):
                        out[r][c] = ray_color
                else:
                    stop = max(marker_cols) if marker_cols else 0
                    for c in range(fixed - 1, stop - 1, -1):
                        out[r][c] = ray_color
    # Marker endpoints remain visible in the dedicated marker color.
    for r, c, _ in singles:
        out[r][c] = 4
    return out

